import {defaults,valueCompany} from './engine.js';
import {mountSimulation} from './simulation-view.js';
import {enterPanel,reducedMotion} from './motion.js';
import {currentSnapshot,draftFor,currentIssues,calculateCurrent,safeDraft,quoteComparison,freezeCurrent,waccWorksheet} from './current-model.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(v,d=1)=>typeof v==='number'&&Number.isFinite(v)?v.toLocaleString('en-US',{maximumFractionDigits:d}):'Unknown';const pc=v=>num(v*100,1)+'%';const safeURL=u=>/^https?:\/\//.test(u||'')?u:'#';
const names=['Evidence','Business story','Revenue','Margins & taxes','Reinvestment','Risk & maturity','Equity claims','Value & simulation'];
let library,content,company,raw,snapshot,draft,marketReferences=null,storageOkay=true;
const app=$('#guided-app');
const sessionDrafts=new Map();
let releaseSimulation=()=>{};
const key=()=>`valuation-lab-guided-v5:${company.ticker}:${raw?.id}`;
const store=()=>{draft.updatedAt=new Date().toISOString();sessionDrafts.set(key(),JSON.stringify(draft));try{localStorage.setItem(key(),JSON.stringify(draft));localStorage.setItem('valuation-lab-guided-selection',JSON.stringify({ticker:company.ticker,id:raw?.id}));}catch{storageOkay=false}const s=$('#guided-save-state');if(s)s.textContent=storageOkay?'Draft saved in this browser · export to keep a durable copy':'Browser storage unavailable · export your draft before leaving';};
function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function choose(ticker,id){company=library.companies.find(c=>c.ticker===ticker)||library.companies[0];raw=company.snapshots?.find(s=>s.id===id)||company.snapshots?.find(s=>s.id===company.currentSnapshotId)||company.snapshots?.find(s=>['ttm','annual-reference'].includes(s.snapshotMode))||company.snapshots?.[0]||{};snapshot=currentSnapshot(company,raw);let saved;try{saved=JSON.parse(sessionDrafts.get(key())||localStorage.getItem(key())||'null')}catch{}draft=safeDraft(saved,company,raw);store();render();}
function change(){draft.reviewed=draft.reviewed.filter(x=>x<draft.step);store();}
function field(k,label,help,scale=100,unit='%',min=0,max=100,step=.5){return `<div class="guided-field"><label for="g-${k}">${label} <span class="assumption-tag">Your assumption</span></label><div class="number-wrap"><input id="g-${k}" type="number" data-assumption="${k}" data-scale="${scale}" value="${Number.isFinite(draft.assumptions[k])?Math.round(draft.assumptions[k]*scale*1e6)/1e6:''}" min="${min}" max="${max}" step="${step}" aria-describedby="g-hint-${k}"><span>${unit}</span></div><small id="g-hint-${k}">${help}</small></div>`}
function note(k,label,placeholder='What evidence supports this? What could make it wrong?'){return `<label for="note-${k}">${label} <span class="assumption-tag">Research note · optional</span></label><textarea id="note-${k}" data-note="${k}" placeholder="${esc(placeholder)}">${esc(draft.notes[k]||'')}</textarea>`}
function table(head,rows){return `<div class="table-wrap"><table><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>'<tr>'+r.map(v=>`<td>${v}</td>`).join('')+'</tr>').join('')}</tbody></table></div>`}
function fact(label,v,key){const e=raw.factEvidence?.[key];return `<div class="fact-tile"><span>${label}</span><b>${num(v)}</b><span>${esc(snapshot.currency)} millions</span><a href="${esc(safeURL(e?.sourceUrl||snapshot.sourceUrl))}" target="_blank" rel="noopener">${e?.formula||e?.derivation||raw.snapshotMode==='ttm'&&['revenue','operatingIncome'].includes(key)?'Derived · filing components':e?.originalInlineVerified||e?.originalDocumentVerified?'Filing verified':'Source / derivation'} ↗</a></div>`}
function evidence(){const r=raw;return `<div class="fact-grid">${fact('Revenue',snapshot.revenue,'revenue')}${fact('Operating profit / EBIT',snapshot.ebit,'operatingIncome')}${fact('Cash & mapped securities',snapshot.cash,'cashAndEquivalents')}${fact('Mapped debt',snapshot.debt,'longTermDebtTotal')}<div class="fact-tile"><span>Economic shares</span><b>${num(snapshot.shares,2)}</b><span>millions · ${esc(snapshot.coverShareDate||'date unverified')}</span></div><div class="fact-tile"><span>Operating margin</span><b>${Number.isFinite(snapshot.revenue)&&Number.isFinite(snapshot.ebit)&&snapshot.revenue>0?pc(snapshot.ebit/snapshot.revenue):'Unknown'}</b><span>Source-based, before your adjustment</span></div></div><details><summary>Trace the numbers to original evidence</summary><p class="micro">${esc(r.derivation||'Reported filing inputs. No automated accounting normalization.')} ${esc(r.cashDefinition||'Cash definition requires review.')} ${esc(r.debtDefinition||'Debt definition requires review.')}</p><p><a href="${esc(safeURL(snapshot.sourceUrl))}" target="_blank" rel="noopener">Open original filing ↗</a> · <a href="./data/current-universe.json" target="_blank" rel="noopener">Full field-level evidence ledger ↗</a></p>${table(['Field','Value','Evidence type'],Object.entries(r.facts||{}).map(([k,v])=>[esc(k),num(v),v===null?'Missing':r.factEvidence?.[k]?.formula||r.factEvidence?.[k]?.derivation?'Derived from verified components':r.factEvidence?.[k]?.originalInlineVerified||r.factEvidence?.[k]?.originalDocumentVerified?'Original filing verified':r.snapshotMode==='ttm'?'Derived / inspect components':'Source-linked']))}<p class="micro">Share basis: ${esc(snapshot.shareBasis||'Unverified')}. Missing does not mean zero. The raw field ledger retains source tags and component periods.</p></details>`}
function stepBody(){switch(draft.step){case 0:return `<div class="guided-fields"><div class="guided-field"><label for="g-cutoff">Valuation date (UTC)</label><input id="g-cutoff" type="date" value="${esc(draft.cutoff)}"><small>A latest-filed dataset is not an as-released historical data service. For historical experiments, use the separate archive.</small></div><div class="guided-field"><label>Model and ownership claim</label><b>Operating-company FCFF</b><small>Nominal ${esc(snapshot.currency)} cash flows; common shares. Banks and insurers need an equity/regulatory-capital model.</small></div></div>${evidence()}${(raw.reviewRequired||[]).length?`<div class="notice"><b>Source review still required</b><ul>${raw.reviewRequired.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}<label class="check-row"><input id="g-model-review" type="checkbox" ${draft.modelReviewed?'checked':''}><span>I understand this is a simplified operating-company model. Replacement capex, capital lead times, NOLs, financing, explicit R&D/lease restatements and award valuation are not separately modeled.</span></label><p class="micro">You can explore every step and save notes with incomplete evidence. Numeric results are withheld for missing essentials or an unsupported security/model.</p>`;
case 1:return `${note('today','Today: who pays, and for what?','Customers, products, segments, pricing and the economic engine…')}${note('change','What changes, and why?','Growth drivers, competitive advantage, disruption, and the next evidence to watch…')}${note('break','What could break the story?','Name one or two falsifiable milestones. A narrative is not automatically a forecast.')}${content.companyPrompts?.[company.ticker]?`<div class="guided-callout">Research prompt: ${esc(content.companyPrompts[company.ticker])}</div>`:''}<details><summary>Normalize the starting point, with an audit trail</summary><p class="micro">Source-based EBIT remains unchanged in the source ledger. A manual net EBIT adjustment enters the calculation. R&D capitalization, leases and SBC require consistent investment/tax/claim treatment beyond this simple delta; do not use it as a substitute for a full restatement.</p><div class="guided-field"><label for="g-normalize">Net EBIT adjustment · ${esc(snapshot.currency)} millions</label><input id="g-normalize" type="number" value="${draft.normalizationDelta}" step="1"><small>Source-based ${num(snapshot.ebit)} + adjustment ${num(draft.normalizationDelta)} = normalized ${num(Number.isFinite(snapshot.ebit)?snapshot.ebit+draft.normalizationDelta:null)} million.</small></div><label for="g-adjust-reason">Why is this adjustment economically appropriate?</label><textarea id="g-adjust-reason">${esc(draft.adjustmentReason)}</textarea><label for="g-adjust-source">Supporting source URL (required for a nonzero adjustment)</label><input id="g-adjust-source" type="url" value="${esc(draft.adjustmentSource)}" style="width:100%"></details>`;
case 2:return `<div class="guided-fields">${field('growth','Initial revenue growth','Fades linearly to stable growth over the ten-year forecast.',100,'%',-50,100,.5)}<div class="guided-field"><label>Forecast horizon</label><b>10 years</b><small>The near-term rate begins in year 1; stable growth arrives in year 10. A different annual path belongs in an explicitly researched historical case.</small></div></div><div id="growth-scale" class="guided-callout"></div>${note('growth','Why this growth path?','Customers × spending, pricing versus volume, capacity, segment mix, or an explicitly dated market size…')}<p class="micro">A market-size estimate is optional if unreliable. Use capacity, customer counts or a historical scale comparison. An untimed management TAM is not a guaranteed sales forecast.</p>`;
case 3:return `<div class="guided-fields">${field('targetMargin','Mature operating margin','EBIT / revenue, not gross or EBITDA margin. Transitions linearly from normalized reported margin.',100,'%',0,100,.5)}${field('tax','Cash tax rate','Applied only to positive EBIT. No automatic tax credit on losses and no NOL carryforward ledger.',100,'%',0,60,.5)}</div><div class="guided-callout">Revenue × operating margin = EBIT. EBIT − cash tax = NOPAT, the after-tax operating earnings available before reinvestment.</div>${note('profit','What supports the margin and tax assumptions?','Competition, pricing, costs, geographic tax mix, temporary relief and limits…')}`;
case 4:return `<div class="guided-fields">${field('salesCapital','Incremental sales / capital','Extra annual revenue generated by each dollar of new invested capital. Higher means less reinvestment.',1,'×',.1,50,.1)}<div class="guided-field"><label>Capital needed for $1 of extra sales</label><b id="capital-per-dollar">${num(1/draft.assumptions.salesCapital,2)}</b><small>Reinvestment = positive revenue increase ÷ sales/capital.</small></div></div><div class="notice">Simplified reinvestment: asset replacement, maintenance schedules, capital lead times and funding are not modeled separately. Declining revenue does not release capital automatically. For capital-heavy businesses, support the simplification or build a richer schedule before relying on value.</div>${note('investment','How will capacity and working capital fund the story?','Review capex, depreciation, maintenance, asset lives, commitments and financing. Recorded for review; separate schedules are not calculated.')}`;
case 5:return `<div class="guided-fields">${field('wacc','Cost of capital (WACC)','Your nominal discount-rate assumption, in the same currency as cash flows. Not a live market estimate.',100,'%',.1,100,.25)}${field('terminalGrowth','Stable growth','Must be below WACC and marginal ROIC. Use a defensible long-run nominal currency growth rate.',100,'%',0,5,.25)}${field('terminalROIC','Mature marginal ROIC','Return on NEW capital, not average historical ROIC. Excess returns need an enduring advantage.',100,'%',.1,100,.5)}<div class="guided-field"><label>Stable reinvestment rate</label><b id="stable-reinvestment">${pc(draft.assumptions.terminalGrowth/draft.assumptions.terminalROIC)}</b><small>g ÷ marginal ROIC. Mature growth consumes cash.</small></div></div><div class="guided-callout">Terminal value = next-year NOPAT × (1 − g / ROIC) ÷ (WACC − g). This includes the investment required to sustain growth.</div>${note('risk','Why this risk and mature competitive position?','Risk-free rate date/currency, business risk, equity premium, debt spread, financing weights, and competition…')}${waccPanel()}<p class="micro">The main model uses the scalar WACC above. The optional worksheet changes it only when you explicitly apply the result. Source dates and risk evidence belong in your note; no risk input is fetched live.</p>`;
case 6:return `<div class="guided-fields">${field('otherAssets','Other nonoperating assets','Add only assets excluded from operating cash flows; review noncurrent securities and cross-holdings.',1,'m',0,1e9,1)}${field('otherClaims','Other claims on equity','Minority/preferred interests, awards, obligations and any additional debt, counted exactly once.',1,'m',0,1e9,1)}</div>${table(['Source bridge item',`${esc(snapshot.currency)} millions`],[['Cash and mapped securities',num(snapshot.cash)],['Mapped debt',num(snapshot.debt)],['Common shares (millions)',num(snapshot.shares,2)]])}<p class="micro">${esc(raw.cashDefinition||'Verify cash restrictions and operating cash.')} ${esc(raw.debtDefinition||'Review debt completeness and leases.')} ${esc(snapshot.shareBasis)} · share date ${esc(snapshot.coverShareDate||'unverified')}.</p>${[...new Set([...(raw.reviewRequired||[]),...(raw.valuationBlockers||[])])].map(x=>`<div class="notice">${esc(x)}</div>`).join('')}${note('claims','How did you treat the unresolved claims?','Zero is an explicit assumption, not evidence of no claims. Explain lease, minority/preferred interest, awards, future SBC and share-basis treatment.')}<label class="check-row"><input id="g-bridge-review" type="checkbox" ${draft.bridgeReviewed?'checked':''}><span>I reviewed cash restrictions, debt and leases, noncontrolling/preferred interests, awards and dilution, share dates and the economic security. My extra-assets and claims inputs are explicit provisional assumptions; unresolved limitations remain visible.</span></label>`;
case 7:return `<div id="guided-results"></div><h3>Check your assumptions</h3><div class="guided-review">${Object.entries({Growth:pc(draft.assumptions.growth),'Mature margin':pc(draft.assumptions.targetMargin),'Cash tax':pc(draft.assumptions.tax),'Sales / capital':num(draft.assumptions.salesCapital)+'×',WACC:pc(draft.assumptions.wacc),'Stable growth':pc(draft.assumptions.terminalGrowth),'Marginal ROIC':pc(draft.assumptions.terminalROIC)}).map(([k,v])=>`<div class="review-row"><span>${k}</span><b>${v}</b></div>`).join('')}</div><p class="micro">All initial inputs are illustrative defaults until you replace or review them. They are not analyst forecasts. Jump to any step to edit.</p>${note('challenge','What new evidence would change your mind?','Downside and upside business stories, unresolved accounting, and milestones to revisit…')}<details id="market-quote"><summary>Add a sourced market quote · optional</summary><p class="micro">No quote feed is connected. A manual quote must match this model’s currency and economic share basis. No expected return or recommendation is inferred.</p><div class="guided-fields"><div class="guided-field"><label for="quote-price">Price per economic share</label><input id="quote-price" data-quote="price" type="number" min=".0001" step=".01" value="${esc(draft.quote.price??'')}"></div><div class="guided-field"><label for="quote-date">Quote date</label><input id="quote-date" data-quote="date" type="date" value="${esc(draft.quote.date)}"></div><div class="guided-field"><label for="quote-currency">Currency code</label><input id="quote-currency" data-quote="currency" type="text" value="${esc(draft.quote.currency)}" placeholder="${esc(snapshot.currency)}"></div><div class="guided-field"><label for="quote-source">Quote source URL</label><input id="quote-source" data-quote="sourceUrl" type="url" value="${esc(draft.quote.sourceUrl)}"></div></div><label class="check-row"><input id="quote-basis" type="checkbox" ${draft.quote.basisConfirmed?'checked':''}> I verified the quote and model refer to the same share class, split basis and currency.</label></details><button id="freeze-current" class="primary">Freeze & export this version ↓</button><p id="freeze-status" class="micro" role="status"></p><details><summary>Original method & limitations</summary><p class="micro">An original educational synthesis inspired by Aswath Damodaran’s public teaching. No affiliation, endorsement, or claim of an exhaustive review of all books and lectures. The model implements a simplified nominal FCFF process, not every accounting and valuation technique discussed.</p><ul class="source-list"><li><a href="https://pages.stern.nyu.edu/~adamodar/pdfiles/ovhds/inv2E/dcfval.pdf" target="_blank" rel="noopener">Damodaran: discounted cash flow framework</a></li><li><a href="https://pages.stern.nyu.edu/~adamodar/New_Home_Page/webcastvalonline.htm" target="_blank" rel="noopener">Official online valuation class</a></li><li><a href="https://pages.stern.nyu.edu/~adamodar/pdfiles/ovhds/inv2E/relval.pdf" target="_blank" rel="noopener">Relative valuation as a cross-check</a></li></ul></details>`;
}}
function results(){releaseSimulation();releaseSimulation=()=>{};const el=$('#guided-results');if(!el)return;let v;try{v=calculateCurrent(snapshot,draft)}catch(e){el.innerHTML=`<div class="error"><b>Valuation not ready</b><br>${esc(e.message)}</div><p class="micro">Your draft and research notes are still usable. Resolve the specific evidence/model issues, or use the historical teaching examples to practice.</p><div class="simulation-gate"><p class="eyebrow">MONTE CARLO · 4,000 POSSIBILITIES</p><h3>Your range starts here.</h3><p>Once the source model and equity claims are reviewed, your assumptions can become an interactive distribution. You can explore this step at any time; narrative notes are optional.</p><div><button id="mc-review-model" class="quiet">Review source & model →</button><button id="mc-review-claims" class="quiet">Review equity claims →</button></div><small>Missing evidence and unsupported models remain gated.</small></div>`;$('#mc-review-model').onclick=()=>go(0);$('#mc-review-claims').onclick=()=>go(6);return}const q=quoteComparison(snapshot,draft,v);el.innerHTML=`<div class="current-result"><div class="hero-result"><p class="eyebrow">UNDER YOUR ASSUMPTIONS · DRAFT ESTIMATE</p><div class="value">${num(v.perShare,2)}<small>${esc(snapshot.currency)} / share</small></div><div class="hero-meta"><div>Operating value<b>${num(v.enterprise,0)}m</b></div><div>Terminal PV share<b>${pc(v.terminalShare)}</b></div><div>Source period<b>${esc(snapshot.periodEnd)}</b></div></div></div><div class="notice">Conditional simplified valuation, not a target price or recommendation. ${raw.snapshotMode==='annual-reference'?'FY baseline; later quarters are not automatically included. ':'TTM flows are derived from dated filings. '}${esc(snapshot.shareBasis)}. Missing or unresolved claims still need judgment.</div><p class="micro">${q.status==='ready'?`Dated quote ${num(q.price,2)} ${esc(snapshot.currency)} on ${esc(q.date)} · value-to-price gap ${pc(q.gap)}. ${esc(q.message)}`:esc(q.message)}</p></div><div id="simulation-lab"></div><h3>Three illustrative economic stresses</h3><div class="scenario-grid">${[['Downside',-.03,-.03,.01],['Your base',0,0,0],['Upside',.03,.03,-.01]].map(([name,g,m,w])=>{let value;try{value=valueCompany({...snapshot,ebit:snapshot.ebit+draft.normalizationDelta,bridgeReviewed:true},{...draft.assumptions,growth:Math.max(-.5,draft.assumptions.growth+g),targetMargin:Math.max(0,Math.min(1,draft.assumptions.targetMargin+m)),wacc:draft.assumptions.wacc+w}).perShare}catch{}return `<article><p>${name}</p><h3>${Number.isFinite(value)?num(value,2):'Invalid'}</h3><small>${pc(Math.max(-.5,draft.assumptions.growth+g))} growth<br>${pc(Math.max(0,Math.min(1,draft.assumptions.targetMargin+m)))} margin<br>${pc(draft.assumptions.wacc+w)} WACC</small></article>`}).join('')}</div><p class="micro">Mechanical stresses: growth ±3 percentage points, margin ±3 points and WACC ∓1 point. Sales/capital and other assumptions held fixed. These are not probabilities or a confidence interval; develop coherent business scenarios in your notes.</p><h3>From enterprise to this share</h3>${table(['Bridge',`${esc(snapshot.currency)} millions`],[['Operating value',num(v.enterprise)],['+ Cash / mapped securities',num(snapshot.cash)],['+ Other assets (assumption)',num(draft.assumptions.otherAssets)],['− Mapped debt',num(snapshot.debt)],['− Other claims (assumption)',num(draft.assumptions.otherClaims)],['Common equity residual',num(v.equity)],['÷ Shares (millions)',num(snapshot.shares,2)]])}${v.equity<0?'<p class="error">Negative common equity residual. Display is floored at zero; distress financing and equity option value are not modeled.</p>':''}<h3>Check the handoff to a mature business</h3>${table(['Measure','Year 10','First stable year'],[['Revenue',num(v.rows.at(-1).revenue),num(v.rows.at(-1).revenue*(1+draft.assumptions.terminalGrowth))],['Operating margin',pc(v.rows.at(-1).margin),pc(draft.assumptions.targetMargin)],['Cash tax rate',pc(draft.assumptions.tax),pc(draft.assumptions.tax)],['Cost of capital',pc(v.rows.at(-1).wacc),pc(draft.assumptions.wacc)],['NOPAT',num(v.rows.at(-1).nopat),num(v.terminalNopat)],['Reinvestment',num(v.rows.at(-1).reinvestment),num(v.terminalReinvestment)]])}<p class="micro">The explicit period uses incremental sales/capital; terminal investment switches to g/ROIC. Check the resulting reinvestment jump. ${draft.assumptions.terminalROIC>draft.assumptions.wacc?'Perpetual ROIC exceeds WACC: explain why new investment earns lasting excess returns.':'Mature investment return does not exceed WACC.'}</p><details><summary>Sensitivity · WACC × stable growth</summary>${table(['WACC / g',...[-.01,0,.01].map(d=>pc(Math.max(0,Math.min(.05,draft.assumptions.terminalGrowth+d))))],[-.01,0,.01].map(w=>[pc(draft.assumptions.wacc+w),...[-.01,0,.01].map(g=>{try{return num(valueCompany({...snapshot,ebit:snapshot.ebit+draft.normalizationDelta,bridgeReviewed:true},{...draft.assumptions,wacc:draft.assumptions.wacc+w,terminalGrowth:Math.max(0,Math.min(.05,draft.assumptions.terminalGrowth+g))}).perShare,2)}catch{return 'Invalid'}})]))}<p class="micro">Terminal reinvestment adjusts with growth. Invalid cells violate the model constraints.</p></details><details><summary>Annual forecast · follow every dollar</summary>${table(['Year','Revenue','Margin','NOPAT','Reinvestment','FCFF','PV FCFF'],v.rows.map(r=>[r.year,num(r.revenue),pc(r.margin),num(r.nopat),num(r.reinvestment),num(r.fcff),num(r.pv)]))}<p class="micro">FCFF is cash flow to all capital providers. A negative projected cash flow signals funding needs; this engine does not construct a financing path.</p></details>`;releaseSimulation=mountSimulation($('#simulation-lab'),snapshot,draft);}
function waccPanel(){return `<details><summary>Build WACC from your evidence · optional worksheet</summary>${marketReferences?.riskFreeReference&&marketReferences?.equityRiskPremiumReference?`<div class="guided-callout"><b>Dated references, not automatic inputs</b><br>USD 10-year Treasury: ${num(marketReferences.riskFreeReference.percentPerYear,2)}% on ${esc(marketReferences.riskFreeReference.observationDate)} · <a target="_blank" rel="noopener" href="${esc(safeURL(marketReferences.riskFreeReference.sourceURL))}">Treasury source ↗</a><br>January 2026 model-implied US equity premium: ${num(marketReferences.equityRiskPremiumReference.percentPerYear,2)}% · <a target="_blank" rel="noopener" href="${esc(safeURL(marketReferences.equityRiskPremiumReference.sourceURL))}">Damodaran source ↗</a><p class="micro">The January ERP is not a current October estimate. Do not mix risk-free/default-adjustment conventions or use a USD rate for other-currency cash flows without a coherent conversion. Beta and company WACC remain your judgments.</p></div>`:""}<p class="micro">Cost of equity = risk-free rate + beta × equity risk premium + country-risk premium. WACC weights equity and after-tax debt by market value. These are your sourced inputs, not live estimates. Country risk must follow operating exposure; avoid counting it twice in beta/ERP or cash flows.</p><div class="guided-fields">${[['riskFree','Risk-free rate',100,'%'],['beta','Levered equity beta',1,'×'],['equityPremium','Equity risk premium',100,'%'],['countryPremium','Additional country-risk premium',100,'%'],['costOfDebt','Pretax cost of debt',100,'%'],['debtWeight','Debt / total market capital',100,'%'],['tax','Marginal tax rate for debt shield',100,'%']].map(([k,label,scale,u])=>`<div class="guided-field"><label for="wacc-${k}">${label}</label><div class="number-wrap"><input id="wacc-${k}" data-wacc="${k}" data-scale="${scale}" type="number" step=".1" min="0" value="${Number.isFinite(draft.waccWorksheet?.[k])?draft.waccWorksheet[k]*scale:''}"><span>${u}</span></div></div>`).join('')}</div><p id="wacc-output" class="guided-callout" role="status"></p><button id="apply-wacc" class="quiet">Apply worksheet WACC to model</button></details>`}
function worksheetResult(){if(!$('#wacc-output'))return;try{const v=waccWorksheet(draft.waccWorksheet);$('#wacc-output').textContent=`Cost of equity ${pc(v.costOfEquity)} · after-tax cost of debt ${pc(v.afterTaxCostOfDebt)} · calculated WACC ${pc(v.wacc)}. Current model WACC remains ${pc(draft.assumptions.wacc)} until applied.`}catch(e){$('#wacc-output').textContent=e.message}}
function refreshDiagnostics(){const a=draft.assumptions;if($('#growth-scale')){let rev=snapshot.revenue;for(let y=1;y<=10;y++)rev*=1+a.growth+(a.terminalGrowth-a.growth)*(y-1)/9;$('#growth-scale').textContent=`This path implies year-10 revenue of ${num(rev,0)} million ${snapshot.currency}, or ${num(rev/snapshot.revenue,1)}× the starting business. Is that scale feasible?`;}if($('#capital-per-dollar'))$('#capital-per-dollar').textContent=num(1/a.salesCapital,2);if($('#stable-reinvestment'))$('#stable-reinvestment').textContent=pc(a.terminalGrowth/a.terminalROIC);results();}
function render(){releaseSimulation();releaseSimulation=()=>{};const s=content.steps[draft.step],issues=currentIssues(snapshot,draft,{includeReview:false});const mode=raw.snapshotMode==='ttm'?'Derived TTM':raw.snapshotMode==='annual-reference'?'Reported FY':raw.snapshotMode==='latest-quarter'?'Interim YTD · evidence only':'Incomplete evidence';app.innerHTML=`<div class="guided-toolbar"><div><label for="current-company">Choose your company</label><select id="current-company">${library.companies.map(c=>`<option value="${esc(c.ticker)}" ${c.ticker===company.ticker?'selected':''}>${esc(c.ticker)} · ${esc(c.name)}</option>`).join('')}</select></div><div><label for="current-snapshot">Financial baseline</label><select id="current-snapshot">${(company.snapshots||[]).map(s=>`<option value="${esc(s.id)}" ${s.id===raw.id?'selected':''}>${esc(s.fiscalLabel||s.snapshotMode+' · '+s.periodEnd)}</option>`).join('')||'<option>Verified data incomplete</option>'}</select></div></div><div class="source-strip"><span class="source-badge">${mode}</span><span>Period: ${esc(snapshot.periodEnd||'unverified')}</span><span>Filed: ${esc(snapshot.filedAt||'unverified')}</span><span>${Number.isFinite(Date.parse(snapshot.periodEnd))?Math.max(0,Math.floor((Date.now()-Date.parse(snapshot.periodEnd))/864e5))+' days since period end':'Period age unknown'}</span><span>Checked: ${esc((raw.retrievedAt||library.retrievedAt||'').slice(0,10)||'unverified')}</span><span>No live quote feed</span></div><div class="info-strip">Dated financial library, checked as of ${esc(library.asOf||'2026-10-17')}. This page does not refresh filings or prices automatically. ${raw.snapshotMode==='annual-reference'?'Annual data may lag the latest quarter. ':''}<a href="#current-data-options" id="data-options-link">Data coverage & import options ↓</a></div>${issues.length?`<div class="error" role="status"><b>Evidence needs attention</b><ul>${issues.map(e=>`<li>${esc(e)}</li>`).join('')}</ul></div>`:''}<div class="guided-layout"><div class="guided-steps" aria-label="Valuation steps">${names.map((name,i)=>`<button class="guided-step ${draft.reviewed.includes(i)?'is-complete':''}" data-step="${i}" aria-current="${draft.step===i?'step':'false'}"><span class="step-index">${draft.reviewed.includes(i)?'✓':String(i+1).padStart(2,'0')}</span><span>${name}</span></button>`).join('')}<p class="guided-utility">Review marks track your work,<br>not forecast confidence.</p></div><div class="guided-card"><div class="guided-progress" aria-hidden="true"><span style="width:${(draft.step+1)/8*100}%"></span></div><p class="eyebrow">STEP ${draft.step+1} OF 8 · ${esc(company.ticker)}</p><h2 id="guided-step-title" tabindex="-1">${esc(s.question)}</h2><p class="guided-lead">${esc(s.why)}</p>${stepBody()}<div class="guided-callout" style="margin-top:24px"><b>Challenge your story</b><br>${esc(s.challenge)}</div><div class="guided-footer"><button class="quiet" id="guided-back" ${draft.step===0?'disabled':''}>← Back</button><span class="step-status">${draft.reviewed.includes(draft.step)?'Reviewed':'Draft · editable'}</span><button class="primary" id="guided-next">${draft.step===7?'Mark reviewed ✓':'Continue →'}</button></div><div class="guided-utility"><span id="guided-save-state"></span> · <button id="export-draft" class="text-button">Export draft ↓</button></div></div></div><details id="current-data-options" class="panel" style="margin-top:24px"><summary>Data coverage, providers & imports</summary><p>14 requested companies are selectable. Financials are staged from public issuer/SEC sources with filing dates and evidence. Missing data and special security/model issues remain visible. This is a dated library, not a real-time stock screener.</p><p class="micro">SEC submissions and XBRL company facts are free, but SEC does not support browser CORS. A production refresh service needs a server-side cache, identified requests, rate controls and audited financial mappings. There is no server-side data refresh or key configured in this release. Alpha Vantage is not connected. This workspace uses the saved 14-company dataset.</p><p><a href="https://www.sec.gov/search-filings/edgar-application-programming-interfaces" target="_blank" rel="noopener">SEC API documentation ↗</a> · <a href="./data/provider-research.html" target="_blank" rel="noopener">Provider feasibility & rights review ↗</a></p><h3>Import a reviewed current company</h3><p class="micro">Local JSON only; nothing is uploaded. Import a company object with ticker, name and snapshots, using the downloadable schema. Use millions, sourced FY/TTM data and an explicit share basis. Imports remain browser-local drafts; export to retain the source object.</p><label for="current-import-file">Company JSON file</label><input id="current-import-file" type="file" accept=".json"><button id="current-template" class="quiet">Download schema ↓</button><p id="current-import-status" role="status"></p><p class="micro">Looking for the preserved NVIDIA and Microsoft cases? Open Historical workbench or Historical research in the navigation. These use a separate information set and never receive current data silently.</p></details>`;
 $('#current-company').onchange=e=>choose(e.target.value);$('#current-snapshot').onchange=e=>choose(company.ticker,e.target.value);
 app.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>go(+b.dataset.step));$('#guided-back').onclick=()=>go(draft.step-1);$('#guided-next').onclick=()=>{if(!draft.reviewed.includes(draft.step))draft.reviewed.push(draft.step);go(Math.min(7,draft.step+1))};$('#export-draft').onclick=()=>download(`${company.ticker}-valuation-draft.json`,{company,raw,draft});
 app.querySelectorAll('[data-assumption]').forEach(el=>el.oninput=()=>{draft.assumptions[el.dataset.assumption]=el.value===''?NaN:Number(el.value)/Number(el.dataset.scale);change();refreshDiagnostics()});app.querySelectorAll('[data-note]').forEach(el=>el.oninput=()=>{draft.notes[el.dataset.note]=el.value;change()});
 if($('#g-cutoff'))$('#g-cutoff').onchange=e=>{draft.cutoff=e.target.value;change();render()};
 for(const [id,k]of [['g-model-review','modelReviewed'],['g-bridge-review','bridgeReviewed']])if($('#'+id))$('#'+id).onchange=e=>{draft[k]=e.target.checked;change()};
 if($('#g-normalize'))$('#g-normalize').onchange=e=>{draft.normalizationDelta=e.target.value===''?NaN:Number(e.target.value);change();render()};for(const [id,k]of [['g-adjust-reason','adjustmentReason'],['g-adjust-source','adjustmentSource']])if($('#'+id))$('#'+id).oninput=e=>{draft[k]=e.target.value;change()};
 app.querySelectorAll('[data-quote]').forEach(el=>el.oninput=()=>{draft.quote[el.dataset.quote]=el.dataset.quote==='price'?(el.value===''?null:Number(el.value)):el.value;store();results()});if($('#quote-basis'))$('#quote-basis').onchange=e=>{draft.quote.basisConfirmed=e.target.checked;store();results()};
 if($('#apply-wacc'))$('#apply-wacc').onclick=()=>{try{const v=waccWorksheet(draft.waccWorksheet);draft.assumptions.wacc=v.wacc;change();render()}catch(e){$('#wacc-output').textContent=e.message}};app.querySelectorAll('[data-wacc]').forEach(el=>el.oninput=()=>{draft.waccWorksheet[el.dataset.wacc]=el.value===''?null:Number(el.value)/Number(el.dataset.scale);change();worksheetResult()});
 if($('#freeze-current'))$('#freeze-current').onclick=()=>{try{const run=freezeCurrent(snapshot,draft);download(`${company.ticker}-valuation-${draft.cutoff}.json`,run);$('#freeze-status').textContent='Frozen version exported. Your draft stays editable; the exported original will not change.'}catch(e){$('#freeze-status').textContent=e.message}};
 $('#data-options-link').onclick=()=>{$('#current-data-options').open=true};$('#current-template').onclick=()=>download('current-company-schema.json',{ticker:'REPLACE',name:'Reviewed operating company',modelType:'operating-fcff',sector:'Technology or other nonfinancial operating sector',currency:'USD',currentSnapshotId:'REPLACE-FY',snapshots:[{id:'REPLACE-FY',snapshotMode:'annual-reference',periodEnd:'2025-12-31',filingDate:'2026-03-01',sourceUrl:'https://www.sec.gov/Archives/REPLACE',currency:'USD',revenue:null,EBIT:null,cash:null,debt:null,shares:null,shareBasis:'Specify actual economic common shares and split convention',sharesAsOf:'2025-12-31',valuationBlockers:['Review cash, debt, leases, claims and dilution.'],backtestEligible:false}]});
 $('#current-import-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2e6)throw Error('Use a JSON file smaller than 2 MB.');const c=JSON.parse(await f.text());if(typeof c.ticker!=='string'||typeof c.name!=='string'||!Array.isArray(c.snapshots)||!c.snapshots.length)throw Error('Expected ticker, name and a nonempty snapshots array.');if(!/^[A-Z0-9.-]{1,12}$/.test(c.ticker)||c.snapshots.some(s=>!s||typeof s.id!=='string')||new Set(c.snapshots.map(s=>s.id)).size!==c.snapshots.length)throw Error('Use a valid ticker and a unique string ID for every snapshot.');library.companies=library.companies.filter(x=>x.ticker!==c.ticker);library.companies.push(c);choose(c.ticker,c.currentSnapshotId);$('#current-data-options').open=true;$('#current-import-status').textContent='Imported locally. Missing fields are flagged, and source/claims review still applies.'}catch(e){$('#current-import-status').textContent=e.message}};
 const stamp=$('.edition-stamp b');if(stamp)stamp.textContent=`${String(draft.step+1).padStart(2,'0')} / 08`;store();refreshDiagnostics();worksheetResult();}
function go(step){const direction=step>=draft.step?1:-1;draft.step=Math.max(0,Math.min(7,step));store();render();enterPanel($('.guided-card'),direction);$('#guided-step-title')?.focus({preventScroll:true});$('#guided-step-title')?.scrollIntoView({block:'start',behavior:reducedMotion()?'auto':'smooth'})}
try{const [l,c]=await Promise.all([fetch('./data/current-universe.json'),fetch('./data/guided-content.json')]);if(!l.ok||!c.ok)throw Error('The dated financial library could not be loaded. Historical cases remain available.');library=await l.json();content=await c.json();try{const mr=await fetch('./data/current-market-references.json');if(mr.ok)marketReferences=await mr.json()}catch{}if(!Array.isArray(library.companies)||!library.companies.length)throw Error('No company records available.');let selection;try{selection=JSON.parse(localStorage.getItem('valuation-lab-guided-selection')||'null')}catch{}choose(selection?.ticker||'AAPL',selection?.id);const openSimulation=$('#open-simulation');if(openSimulation)openSimulation.onclick=()=>go(7);}catch(e){app.innerHTML=`<div class="error">${esc(e.message)}</div>`;}
